// Original lessons. Running case: HarbourFest stalls, tickets and local services.
import { M, F, A, tbl } from './helpers.js';
import { glossary2 } from './glossary2.js';
const C = (title, html) => ({title,html});
const Q = (q, options, answer, why, cmd='Identify') => ({type:'mcq',q,options,answer,why,cmd});
const T = (q, answer, why) => ({type:'tf',q,answer,why});
const N = (q, rows, answer, why, unit='') => ({type:'num',cmd:'Calculate',q:q+tbl(['Item','Value'],rows.concat([['Your answer',A(answer,true)]])),answer,why,unit,tol:0.01});
const S = (title,buckets,items) => ({type:'sort',title,challenge:'Classify every item correctly to complete the challenge.',buckets,items:items.map(([t,b])=>({t,b}))});
const W = (title,intro,steps,takeaway) => ({title,intro,steps:steps.map(([prompt,answer])=>({prompt,answer})),takeaway});
const H = '<span class="tag">HL</span> ';
// Labelled schematic diagrams: curves illustrate relationships, not estimated data.
const market = (caption, extra='') => `<figure><svg viewBox="0 0 350 250" role="img" aria-label="${caption}" style="width:100%;max-width:420px"><path d="M45 15V210H335" fill="none" stroke="currentColor" stroke-width="2"/><path d="M65 40L305 190" fill="none" stroke="var(--chart-1)" stroke-width="3"/><path d="M65 190L305 40" fill="none" stroke="var(--chart-3)" stroke-width="3"/><path d="M45 115H185V210" fill="none" stroke="currentColor" stroke-dasharray="5 4"/><g fill="currentColor" font-size="13"><text x="3" y="15">Price</text><text x="230" y="241">Quantity / period</text><text x="307" y="194">D</text><text x="307" y="40">S</text><text x="15" y="119">Pe</text><text x="176" y="228">Qe</text></g>${extra}</svg><figcaption>${caption}</figcaption></figure>`;
const externalDiagram = `<figure><svg viewBox="0 0 370 255" role="img" aria-label="Negative production externality: MSC above MPC, market output exceeds efficient output, welfare loss shaded" style="width:100%;max-width:440px"><path d="M40 20V210H335" fill="none" stroke="currentColor" stroke-width="2"/><path d="M60 40L320 170" stroke="var(--chart-1)" stroke-width="3"/><path d="M60 210L320 80" stroke="var(--chart-3)" stroke-width="3"/><path d="M60 160L320 30" stroke="var(--chart-4)" stroke-width="3"/><path d="M180 100L230 125V75Z" fill="color-mix(in srgb, var(--chart-4) 25%, transparent)"/><path d="M180 100V210M230 125V210" stroke="currentColor" stroke-dasharray="5 4"/><g fill="currentColor" font-size="12"><text x="3" y="14">Cost / benefit</text><text x="324" y="31">MSC</text><text x="324" y="82">MPC</text><text x="245" y="192">MPB = MSB</text><text x="160" y="227">Qopt</text><text x="221" y="227">Qm</text><text x="240" y="248">Quantity / period</text></g></svg><figcaption>Negative production externality. The market chooses Qm at MPB = MPC; efficient Qopt is at MSB = MSC. The shaded triangle is welfare lost through overproduction.</figcaption></figure>`;
const firmDiagram = `<figure><svg viewBox="0 0 370 255" role="img" aria-label="Profit-making price-setting firm: output at MC equals MR, price read from AR, profit rectangle above AC" style="width:100%;max-width:440px"><path d="M40 20V210H330" fill="none" stroke="currentColor" stroke-width="2"/><path d="M40 87H179V140H40Z" fill="color-mix(in srgb, var(--good) 20%, transparent)"/><path d="M50 35L320 143" stroke="var(--chart-1)" stroke-width="3"/><path d="M50 35L265 207" stroke="var(--chart-2)" stroke-width="3"/><path d="M60 186L320 82" stroke="var(--chart-4)" stroke-width="3"/><path d="M70 70Q160 210 305 70" stroke="var(--chart-3)" stroke-width="3" fill="none"/><path d="M40 87H179V210M40 140H179" stroke="currentColor" stroke-dasharray="5 4" fill="none"/><g fill="currentColor" font-size="12"><text x="3" y="14">Cost / revenue</text><text x="326" y="146">AR</text><text x="267" y="209">MR</text><text x="324" y="81">MC</text><text x="305" y="65">AC</text><text x="12" y="90">Pm</text><text x="12" y="143">AC</text><text x="168" y="228">Qm</text><text x="235" y="248">Output / period</text></g></svg><figcaption>Schematic price-setting firm. Find Qm at MC = MR, then move up to AR for Pm. The shaded rectangle shows positive economic profit, (Pm − AC) × Qm. AC at Qm is read from the labelled AC curve.</figcaption></figure>`;
const sections = [
{
id:'2.1',title:'Demand: what makes the queue grow?',emoji:'🎟️',minutes:12,hl:'part',
goal:'distinguish movements from demand shifts and explain the HL foundations of demand.',
hook:'<p>HarbourFest drops the ticket price and your friends buy more tickets. A viral clip then brings in a whole new crowd at every price. Both sales changes look similar in the booking app. Do they mean the same thing on a demand diagram?</p>',
cards:[C('Willing and able','<p><b>Demand</b> is the quantity consumers are willing and able to buy at different prices over a period. The <b>law of demand</b> states that quantity demanded generally falls as own price rises, other things equal.</p><div class="example">Wanting a VIP ticket without the money to buy it is not effective demand. A cheaper ticket causes movement along the existing demand curve.</div>'+market('For a demand curve, read the blue line: higher own price corresponds to lower quantity demanded.')),
C('A different curve','<p>Income, preferences, expected future prices, related-good prices and the number of buyers shift demand. A <b>substitute</b> can replace another good; a <b>complement</b> is used with it.</p><div class="example">A rival festival raises its price: demand for HarbourFest may shift right. More expensive travel, a complement, may shift ticket demand left. Higher income raises demand for a normal good but lowers demand for an inferior good.</div><div class="tip">Explain: name the determinant, its direction and why more or fewer tickets are wanted at the same price.</div>'),
C('From one fan to the market','<p><b>Market demand</b> is the horizontal sum of individual quantities demanded at each price, for the same period. Add quantities, not prices.</p>'+tbl(['At DKK 100','Tickets wanted'],[['Freja','2'],['Ali','3'],['Market total','5']])+'<p>A demand increase means the whole curve moves right. An increase in quantity demanded means movement down an unchanged curve.</p>'),
C('HL: why downward? ',H+'<p><b>Diminishing marginal utility</b> means the extra satisfaction from successive units tends to decline. With rational utility-maximising behaviour, an extra ticket needs a lower price to make its smaller extra benefit worthwhile.</p><p>The <b>substitution effect</b> means a price fall makes this good cheaper relative to alternatives. The <b>income effect</b> means the same money buys more: purchasing power rises. For a normal good both support higher quantity demanded. These explanations rely on assumptions about preferences, information and other prices.</p>')],
labs:[S('Why did bookings change?',['Along demand','Demand shifts right','Demand shifts left'],[['HarbourFest lowers its own price',0],['A popular artist joins the same-price line-up',1],['A rival festival becomes cheaper',2],['Rail fares to HarbourFest rise',2],['More potential ticket buyers move nearby',1],['HarbourFest raises its own price',0]])],
worked:W('Separate two sales stories','<p>HarbourFest measures tickets wanted per weekend.</p>'+tbl(['Situation','Own ticket price','Tickets wanted'],[['Before','100','400'],['Own-price cut','80','500']]),[['Which variable changed first?','The ticket’s own price fell; other determinants are assumed unchanged.'],['Which diagram change follows?','Move down and right along demand, from quantity 400 to 500.'],['What if a viral clip later raises sales at every price?','That is an increase in demand: shift the entire demand curve right.'],['How should you label it?','Price in DKK vertically; tickets per weekend horizontally; D1 and D2 for separate curves.']],'Always identify the cause before deciding whether to move or shift.'),
quiz:[Q('Which is effective demand?',['Wanting and being able to pay for a ticket','Wanting a ticket with no ability to pay','Every person who likes music','The tickets sellers offer'],0,'Demand requires both willingness and ability to buy.'),Q('HarbourFest cuts its own ticket price, other things equal. What occurs?',['Movement along demand','Demand shifts right','Demand shifts left','Supply shifts left'],0,'Own price changes quantity demanded along a given curve.'),Q('A close rival raises its ticket price. HarbourFest demand is likely to…',['Shift right','Shift left','Disappear','Become supply'],0,'Some buyers substitute towards HarbourFest at each own price.'),N('Add market demand at the same price.',[['Freja’s quantity','3'],['Ali’s quantity','4']],7,'Horizontal aggregation adds 3 + 4 = 7 tickets.','tickets'),T(H+'Diminishing marginal utility means total utility must fall with every extra unit.',false,'Marginal utility can fall while remaining positive, so total utility still increases.'),Q('A more expensive train fare reduces ticket purchases at every ticket price. Why?',['Travel is a complement','Travel is a substitute','Own ticket price fell','Market demand is a vertical sum'],0,'A higher complement price makes the combined visit more costly.')],
explain:'Text a friend two reasons why the ticket queue got longer: one movement and one shift. Label the cause of each.'
},
{
id:'2.2',title:'Supply: can the stalls keep up?',emoji:'🥙',minutes:12,hl:'part',goal:'explain supply shifts, market supply and the HL law of diminishing returns.',
hook:'<p>The noodle stall sees higher meal prices and prepares more bowls. Then a cheaper cooker changes how many bowls it can profitably offer at every price. Freja keeps calling both changes “more supply”. Help her separate them.</p>',
cards:[C('An offer at every price','<p><b>Supply</b> is the quantity producers are willing and able to offer at different prices over a period. The <b>law of supply</b> describes the usual positive relationship between own price and quantity supplied, other things equal.</p><div class="example">A higher bowl price can cover the additional cost of extra preparation. This is movement up the supply curve, not a shift.</div>'+market('Read the green supply line: higher own price encourages greater quantity supplied.')),
C('Change the conditions','<p>Input costs, technology, indirect taxes, subsidies, producer numbers and expectations can shift supply. Cheaper energy or a better cooker shifts supply right. Higher ingredient costs or a per-bowl tax shifts it left.</p><p><b>Joint supply</b> occurs when products arise together: greater leather production may accompany more beef production. In <b>competitive supply</b>, products compete for resources: higher wrap prices may divert the same kitchen away from noodles.</p>'),
C('Add stalls, not price tags','<p><b>Market supply</b> is the horizontal sum of producers’ quantities supplied at each price. More sellers generally shift market supply right.</p><div class="example">At DKK 50, two stalls offer 60 and 40 bowls per hour: market quantity supplied is 100. If sellers expect a higher future price and can store the good, they may reduce current supply. Perishable meals limit that response.</div><div class="tip">Distinguish: compare an own-price movement with one specific non-price shift.</div>'),
C('HL: fixed kitchens, rising extra costs',H+'<p>The <b>law of diminishing marginal returns</b> states that adding a variable input to fixed inputs eventually produces smaller extra output, other things equal. <b>Marginal cost</b> is the cost of one additional unit of output.</p><div class="example">With one fixed cooker, extra workers eventually crowd each other. If each worker is paid the same wage, smaller extra output raises cost per extra bowl. Rising marginal cost helps explain upward-sloping supply. Diminishing returns is a short-run idea; it is not a claim that total output immediately falls.</div>')],
labs:[S('Kitchen supply board',['Along supply','Supply shifts right','Supply shifts left'],[['The bowl’s own price rises',0],['A cheaper energy contract starts',1],['A per-bowl tax increases',2],['More stalls enter the market',1],['Ingredient costs rise',2],['A cooker raises output per worker',1]])],
worked:W('From one cooker to market supply','<p>At the same DKK 50 meal price, Stall A offers 60 bowls and Stall B offers 40 per hour.</p>',[['What is market quantity supplied?','60 + 40 = 100 bowls per hour at that price.'],['What if the meal price rises?','With other determinants fixed, move up and right along each supply curve.'],['What if ingredients become cheaper instead?','At every meal price, production becomes more profitable: supply shifts right.'],['HL: why might extra output get costly?','The cooker is fixed; diminishing extra output per additional worker can raise marginal cost.']],'State the time period and hold the comparison price constant when describing a shift.'),
quiz:[Q('A rise in the meal’s own price causes…',['An increase in quantity supplied','A leftward supply shift','A rightward demand shift','A fall in market supply by definition'],0,'Own price causes movement along supply.'),Q('Which most directly shifts meal supply right?',['Cheaper ingredients','Higher energy costs','A higher per-meal tax','Fewer stalls'],0,'Lower input costs allow more profitable production at each price.'),N('Calculate market supply at DKK 50.',[['Stall A bowls/hour','60'],['Stall B bowls/hour','40']],100,'60 + 40 = 100 bowls per hour.','bowls/hour'),T(H+'Diminishing marginal returns requires at least one fixed input.',true,'The short-run argument adds a variable input while other productive inputs stay fixed.'),Q('Wraps and noodles use the same limited cooker. Higher wrap prices may…',['Shift noodle supply left','Shift noodle demand right automatically','Remove all opportunity cost','Increase both supplies without a trade-off'],0,'Resources can move towards wraps: the goods are in competitive supply.'),Q(H+'If extra output per worker falls while the wage stays fixed, marginal cost tends to…',['Rise','Fall to zero','Stay zero','Equal total revenue'],0,'The same wage now pays for fewer extra bowls.')],
explain:'Explain why a new cooker shifts supply but a higher bowl price causes movement along supply. Add one fixed-input warning.'
},
{
id:'2.3',title:'Equilibrium and the price signal',emoji:'⚖️',minutes:14,hl:'part',goal:'trace equilibrium changes, explain the price mechanism and calculate HL surpluses.',
hook:'<p>At DKK 20, the juice stall sells out before lunch. At DKK 60, unsold juice fills the fridge. The organiser wants one price that clears the market. Is the market-clearing price also the fairest price?</p>',
cards:[C('Where plans agree','<p><b>Market equilibrium</b> occurs where quantity demanded equals quantity supplied. <b>Excess demand</b> is a shortage at a price below equilibrium; <b>excess supply</b> is a surplus at a price above it.</p><div class="example">A shortage gives sellers an incentive to raise price, reducing quantity demanded and encouraging quantity supplied. This describes pressure, not an instant guaranteed adjustment.</div>'+market('The intersection gives equilibrium price Pe and quantity Qe.')),
C('What prices do','<p>The <b>price mechanism</b> signals relative scarcity, creates incentives to adjust production and rations scarce output among buyers willing and able to pay.</p><div class="example">Higher juice demand first creates a shortage at the old price. The eventual higher price attracts more output and discourages some purchases. A supply increase instead tends to lower equilibrium price and raise equilibrium quantity.</div><p>When both curves shift, one outcome can be ambiguous. Higher demand and lower supply both raise price, but their effects on quantity oppose each other.</p>'),
C('Gains from exchange','<p><b>Consumer surplus</b> is the difference between willingness to pay and the price paid, summed over purchases. <b>Producer surplus</b> is revenue above the minimum supply price, summed over sales; it is not identical to profit.</p><p><b>Social surplus</b> is consumer plus producer surplus. <b>Allocative efficiency</b> means resources produce the combination maximising social surplus, where marginal social benefit equals marginal social cost. Competitive equilibrium achieves this in the model only if demand and supply reflect all social benefits and costs, with no relevant market failure.</p>'),
C('HL: measure the triangles',H+F`CS=\frac{1}{2}\times Q_e\times(P_{\max}-P_e)`+F`PS=\frac{1}{2}\times Q_e\times(P_e-P_{\min})`+'<div class="example">For straight curves, Qe = 100 cups, Pe = 40, demand intercept = 60 and supply intercept = 20: CS = DKK 1,000; PS = DKK 1,000.</div><div class="tip">Analyse: draw the original curves, mark the shift, explain the shortage or surplus at the original price, then identify the new equilibrium. Efficiency alone does not establish equity.</div>')],
labs:[{type:'equilibrium',title:'Move the market curves',mode:'market',challenge:'Shift demand and supply and compare equilibrium.'},S('Market pressure',['Upward price pressure','Downward price pressure','Ambiguous quantity effect'],[['Shortage at the current price',0],['Unsold stock at the current price',1],['Demand rises while supply falls',2],['Supply rises with demand unchanged',1],['Demand rises with supply unchanged',0]])],
worked:W('Who gains from a juice market?','<p>The straight-line juice curves cross at the following values.</p>'+tbl(['Diagram feature','Value'],[['Equilibrium quantity','100 cups'],['Equilibrium price','DKK 40'],['Demand price intercept','DKK 60'],['Supply price intercept','DKK 20']]),[['HL: what area is consumer surplus?','Triangle below demand and above price, from zero to 100 cups: 0.5 × 100 × (60 − 40) = DKK 1,000.'],['HL: what area is producer surplus?','Triangle above supply and below price: 0.5 × 100 × (40 − 20) = DKK 1,000.'],['What does a DKK 30 market price create?','A shortage: quantity demanded exceeds quantity supplied, creating upward price pressure.'],['Does maximum surplus prove fairness?','No. Benefits depend on purchasing power and ownership, and the model assumes no external costs or benefits.']],'Name the model assumptions before calling the outcome socially efficient.'),
quiz:[Q('At equilibrium…',['Quantity demanded equals quantity supplied','Everyone can afford the good','Supply is always vertical','There is no scarcity'],0,'The market clears; it does not eliminate scarcity or inequality.'),Q('At a price below equilibrium, the market has…',['Excess demand','Excess supply','No demand','A supply shift by definition'],0,'Buyers want more than sellers offer at that price.'),Q('Demand rises while supply falls. Which outcome is definite?',['Equilibrium price rises','Equilibrium quantity rises','Equilibrium quantity falls','Price falls'],0,'Both changes push price up; the quantity effect depends on relative shifts.'),N(H+'Find consumer surplus for straight demand.',[['Qe (cups)','100'],['Maximum willingness to pay (DKK)','60'],['Pe (DKK)','40']],1000,'0.5 × 100 × (60 − 40) = DKK 1,000.','DKK'),T('Producer surplus always equals accounting profit.',false,'Producer surplus does not subtract every cost; it is revenue above minimum supply prices.'),Q('Why might equilibrium fail to maximise social surplus?',['Unpriced pollution affects neighbours','Curves intersect','Buyers compare prices','Sellers respond to incentives'],0,'External costs mean private supply does not reflect the whole social cost.')],
explain:'Text the juice stall why a queue can signal a shortage. Then explain why a market-clearing price need not be fair.'
},
{
id:'2.4',title:'HL: choices, nudges and business goals',emoji:'🧠',minutes:13,hl:true,goal:'evaluate rational-choice assumptions, behavioural interventions and alternative firm objectives.',
hook:'<p>The booking app preselects an expensive upgrade. Your friend keeps it because cancelling needs extra taps, although they planned a cheap night. A stall also refuses a profitable disposable-cup deal. Are all these decisions best explained by perfect calculation and maximum profit?</p>',
cards:[C('An assumption to test',H+'<p><b>Rational consumer choice</b> models consumers as consistent, informed decision-makers maximising utility within a budget. Perfect information is a demanding assumption.</p><p><b>Bounded rationality</b> means limited time, information or processing capacity constrain decisions. <b>Bounded self-control</b> explains choosing immediate temptation against longer-run plans. <b>Bounded selfishness</b> recognises fairness and others’ welfare can matter.</p><div class="example">You may donate to a flood appeal even when that leaves less money for your own festival upgrades.</div>'),
C('Predictable shortcuts',H+'<p>A <b>rule of thumb</b> simplifies decisions. <b>Anchoring</b> gives an initial figure disproportionate influence; <b>framing</b> means presentation affects choices; <b>availability bias</b> gives memorable, easily recalled information too much weight.</p><div class="example">“Was 1,000, now 600” may anchor your judgement even if 1,000 was never a typical price. One vivid theft video may distort your estimate of festival risk. These mechanisms differ; name the actual cue.</div>'),
C('Designing the choice setting',H+'<p><b>Choice architecture</b> is how options are presented. A <b>default</b> applies unless you actively choose otherwise. A <b>nudge</b> changes the choice setting predictably while keeping options available and avoiding large financial incentives.</p><p>Restricted choice removes some options; mandated choice requires an active selection. These can alter behaviour but are not automatically nudges. A preselected reusable cup is a default; a ban on disposables is restriction. Evaluate transparency, ease of opting out, evidence of effectiveness and whose welfare improves.</p>'),
C('What is the stall trying to achieve?',H+'<p><b>Profit maximisation</b> seeks the largest gap between total revenue and economic cost. Alternative objectives include growth, <b>market share</b> (a firm’s fraction of total market sales), <b>satisficing</b> (meeting a satisfactory target) and <b>corporate social responsibility</b> (considering wider social and environmental effects).</p><div class="example">A stall might accept lower short-run profit to use fair-pay suppliers, build loyal demand or make its owner’s working hours manageable. CSR may support future profit, so objectives can overlap.</div><div class="tip">Evaluate: compare the predicted behaviour with evidence, identify competing goals and explain which objective fits this context.</div>')],
labs:[S('Spot the decision mechanism',['Anchoring','Default','Bounded self-control','Alternative firm objective'],[['A preselected reusable cup remains unless unticked',1],['An inflated original price shapes your bargain judgement',0],['You buy an upgrade despite your earlier savings plan',2],['A stall prioritises a reasonable income and free evenings',3],['The stall accepts lower profit to pay suppliers fairly',3]])],
worked:W('Should the cup be preselected?','<p>HarbourFest proposes a refundable reusable-cup option as the booking default.</p>',[['Which mechanism is being used?','Default choice architecture may exploit inertia or limited attention. Buyers can actively opt out.'],['Why might it help?','If returns rise and lifecycle waste falls, it may reduce environmental harm without removing choice.'],['What evidence is needed?','Compare return rates, actual material use, washing and transport costs, and complaints before and after a controlled trial.'],['What is a justified judgement?','Use a transparent default with a simple opt-out if measured benefits exceed costs; change it if it traps people in unwanted charges.']],'A label such as nudge does not establish effectiveness or ethical acceptability.'),
quiz:[Q('A consumer lacks time to compare 200 ticket packages. This illustrates…',['Bounded rationality','Perfect information','Unlimited processing capacity','Market clearing'],0,'Limited time and attention constrain fully optimising choice.'),Q('“Originally DKK 1,000” shapes the judgement of a DKK 600 ticket. Which bias?',['Anchoring','Availability alone','Diminishing supply','Market share'],0,'The initial number serves as a reference point.'),T('A ban that removes disposable cups is a nudge by definition.',false,'Restriction removes an option; a nudge preserves options and avoids large incentive changes.'),Q('Which is a mandated choice?',['You must select yes or no before continuing','An option is automatically selected','Every option is banned','A DKK 1,000 subsidy is offered'],0,'Mandated choice requires an active decision rather than a preselected answer.'),Q('A stall seeks an acceptable income rather than the largest possible profit. It is…',['Satisficing','Always making a loss','Maximising market share necessarily','Perfectly informed by definition'],0,'Satisficing aims for a sufficient target.'),N('Find the stall’s market share by sales value.',[['Stall revenue (DKK)','20,000'],['Total market revenue (DKK)','100,000']],20,'20,000 / 100,000 × 100 = 20%.','%')],
explain:'Text a mate how one booking-screen design affects you. Judge when that intervention would help and when it would manipulate.'
},
{
id:'2.5a',title:'Price elasticity: should tickets cost more?',emoji:'🪢',minutes:14,hl:'part',goal:'calculate PED and revenue changes, explain its determinants and HL variation along demand.',
hook:'<p>Freja wants to raise ticket prices to fund a better stage. You worry buyers will leave for a rival festival. The same price rise could increase or reduce revenue. How responsive are your buyers?</p>',
cards:[C('Sensitivity in percentages','<p><b>Price elasticity of demand (PED)</b> measures how responsive quantity demanded is to a change in price.</p>'+F`PED=\frac{\%\Delta Q_d}{\%\Delta P}`+'<p>Normal downward demand gives a negative coefficient. Use its absolute magnitude when classifying: above 1 elastic, below 1 inelastic, equal to 1 unit elastic. Zero is perfectly inelastic (vertical); an infinite response is perfectly elastic (horizontal).</p><div class="example">Price rises 10% and quantity falls 20%: signed PED = −2; magnitude 2 is elastic.</div>'),
C('What gives buyers options?','<p>More close substitutes, a larger share of income, less necessity and more adjustment time usually make demand more elastic.</p><div class="example">A specific festival brand has many rivals; all entertainment together has fewer substitutes. Emergency medicine is often less responsive than optional upgrades. Demand tends to become more elastic over time as buyers find alternatives.</div><p>Do not compare steepness without the same scales: slope uses units, elasticity uses percentages.</p>'),
C('The revenue test','<p><b>Total revenue</b> is price times quantity sold.</p>'+F`TR=P\times Q`+'<p>For elastic demand, a price rise lowers total revenue; for inelastic demand it raises revenue. At unit elasticity a small price change leaves revenue approximately unchanged. Revenue is not profit: production costs can change too.</p><div class="example">Price 100 → 110 and sales 1,000 → 800 changes revenue from DKK 100,000 to DKK 88,000. Buyers’ quantity response outweighs the price rise.</div>'),
C('HL: a straight line is not one elasticity',H+'<p>On a straight downward demand curve, slope is constant but PED varies: the high-price, low-quantity region is elastic; the midpoint is unit elastic; the low-price, high-quantity region is inelastic. A curve with unit elasticity everywhere is a rectangular hyperbola, not a straight line.</p><p>Basic primary commodities often have fewer close substitutes and are necessities, making demand relatively inelastic; individual manufactured brands may have many alternatives. These are tendencies, not universal rules. Governments use PED when forecasting tax revenue and consumption effects.</p><div class="tip">Calculate: show percentage changes using the initial values unless another method is specified, then interpret the magnitude.</div>')],
labs:[S('Revenue adviser',['Price rise tends to raise revenue','Price rise tends to lower revenue','Insufficient information about profit'],[['PED magnitude is 0.4',0],['PED magnitude is 2.0',1],['PED magnitude is 1.5',1],['Revenue rises but production costs are unknown',2],['PED magnitude is 0.1',0]])],
worked:W('Will the stage upgrade pay?','<p>Use initial-value percentages.</p>'+tbl(['Measure','Before','After'],[['Ticket price (DKK)','100','110'],['Tickets sold','1,000','800']]),[['What is the percentage price change?','(110 − 100) / 100 × 100 = 10%.'],['What is the quantity change?','(800 − 1,000) / 1,000 × 100 = −20%.'],['What is PED?','−20 / 10 = −2. The magnitude is 2: demand is elastic over this observed change.'],['What happens to revenue?','100 × 1,000 = 100,000; 110 × 800 = 88,000. Revenue falls by DKK 12,000.']],'Revenue arithmetic checks the elasticity prediction; profit still requires cost data.'),
quiz:[N('Calculate the magnitude of PED.',[['Price change','+10%'],['Quantity demanded change','−20%']],2,'The signed value is −2; its magnitude is 2.'),Q('When demand is price elastic, a price increase tends to…',['Reduce total revenue','Increase total revenue always','Leave revenue unchanged always','Remove costs'],0,'The percentage quantity reduction exceeds the percentage price increase.'),Q('Which tends to make demand more elastic?',['More close substitutes','Fewer alternatives','A greater degree of necessity','Less adjustment time'],0,'Buyers can switch away more easily.'),N('Find new revenue.',[['New price (DKK)','110'],['New quantity','800']],88000,'TR = 110 × 800 = DKK 88,000.','DKK'),T(H+'A straight downward demand curve has the same PED at every point.',false,'The price-to-quantity ratio changes along the line, so elasticity varies even with constant slope.'),Q('Perfectly inelastic demand is drawn…',['Vertically','Horizontally','As an upward line','As the supply curve only'],0,'Quantity demanded does not change when price changes.')],
explain:'Text Freja why a higher ticket price might leave less revenue for the stage. Mention substitutes and explain why revenue is not profit.'
},
{
id:'2.5b',title:'Income elasticity and changing demand',emoji:'💶',minutes:11,hl:'part',goal:'calculate YED, classify goods and explain HL implications for firms and economic structure.',
hook:'<p>Your summer wages rise and you buy more festival upgrades. You buy fewer cheap packed lunches because you can now afford fresh meals. Both changes follow higher income. What does the sign of the response tell you?</p>',
cards:[C('Income changes, price held constant','<p><b>Income elasticity of demand (YED)</b> measures how responsive demand is to a change in consumer income, holding relevant other factors constant.</p>'+F`YED=\frac{\%\Delta Q_d}{\%\Delta Y}`+'<p>A <b>normal good</b> has positive YED. An <b>inferior good</b> has negative YED: demand falls as income rises. Inferior describes the income relationship, not poor quality or moral value.</p>'),
C('Necessities and luxuries','<p>For normal goods, YED between zero and one describes income-inelastic demand, often necessities. Above one means income-elastic demand, often luxuries. At one, demand rises in the same percentage as income.</p><div class="example">Income rises 10%. Bread purchases rise 2%: YED 0.2. VIP upgrades rise 20%: YED 2. Budget lunch purchases fall 5%: YED −0.5. Classification may differ across people and income ranges.</div>'),
C('Draw an Engel curve','<p>An <b>Engel curve</b> relates income to quantity demanded, with the good’s own price and other determinants fixed. Label income vertically and quantity horizontally, and state that convention.</p><p>A normal good slopes upward in this convention; an inferior-good segment slopes downward. Identify elasticity from percentage changes, not a vague claim that “steeper means luxury”. An income change shifts the ordinary price–quantity demand curve.</p>'),
C('HL: follow the next pay rise',H+'<p>Firms can use YED to plan capacity and product ranges. A luxury stall may grow quickly as incomes rise but suffer a large sales fall in recession. Estimates depend on the customer group and can change.</p><p>As average incomes rise, demand for many services and manufactured goods may grow faster than demand for basic food. Employment and output shares can shift across sectors, but productivity, trade and institutions also matter. Positive food demand growth can coexist with a falling food share of total spending.</p><div class="tip">Explain: connect the coefficient to a direction and size of demand response, then qualify the forecast.</div>')],
labs:[S('Classify the income response',['Inferior','Normal necessity','Normal luxury'],[['YED = −0.4',0],['YED = 0.3',1],['YED = 1.8',2],['Demand falls when income rises',0],['Demand grows more slowly than income',1],['Demand grows faster than income',2]])],
worked:W('Follow a summer pay rise','<p>Own prices and other influences are held fixed.</p>'+tbl(['Measure','Change'],[['Income','+10%'],['VIP demand','+20%'],['Budget-lunch demand','−5%']]),[['What is VIP YED?','20 / 10 = 2: a normal, income-elastic luxury in this example.'],['What is budget-lunch YED?','−5 / 10 = −0.5: an inferior good for these consumers over this income range.'],['HL: how might the sellers respond?','VIP sellers may plan for stronger growth when incomes rise; budget sellers may change their range. Both should check whether the estimate applies to their actual customers.']],'Retain the sign for YED; it carries information that a magnitude alone loses.'),
quiz:[N('Calculate YED.',[['Income change','+10%'],['Demand change','−5%']],-0.5,'−5 / 10 = −0.5. Retain the negative sign.'),Q('A negative YED identifies…',['An inferior good','A normal necessity','A luxury necessarily','A good nobody wants'],0,'Demand decreases as income increases, other things equal.'),Q('YED = 0.4 describes…',['A normal necessity','An inferior good','A luxury with YED above one','Perfectly elastic supply'],0,'The coefficient is positive but below one.'),T('“Inferior” means the product must be low quality.',false,'It describes a demand response to income, not an objective quality judgement.'),Q(H+'Which business is most exposed to income fluctuations, all else equal?',['One with YED = 2.5','One with YED = 0.1','Both must have identical exposure','YED cannot concern income'],0,'A larger positive YED implies a larger percentage sales response to income changes.'),Q('An Engel curve holds which variable constant?',['The good’s own price','Consumer income','Quantity demanded','The sign of YED by definition'],0,'It isolates the relationship between income and quantity demanded.')],
explain:'Use your own spending to explain one necessity, one luxury and one possible inferior good. Explain why the labels can differ between people.'
},
{
id:'2.6',title:'Supply elasticity and festival capacity',emoji:'🏭',minutes:11,hl:'part',goal:'calculate PES and explain how time, capacity and production conditions affect supply response.',
hook:'<p>A surprise headliner doubles demand for food. The snack stall can unpack stored crisps immediately, while the fresh-fruit grower cannot create another harvest overnight. Both see higher prices. Why does only one expand quickly?</p>',
cards:[C('Can output respond?','<p><b>Price elasticity of supply (PES)</b> measures the responsiveness of quantity supplied to a price change.</p>'+F`PES=\frac{\%\Delta Q_s}{\%\Delta P}`+'<p>Supply is elastic above 1, inelastic between 0 and 1, and unit elastic at 1. Perfectly inelastic supply is vertical; perfectly elastic supply is horizontal. Conventional supply gives a non-negative coefficient.</p>'),
C('Capacity, stores and mobility','<p>Spare capacity, stored stocks and mobile resources allow a larger response. Steeply rising extra costs or specialised inputs limit it.</p><div class="example">Crisps can be stored and shifted from another shop. Fresh berries perish, and extra trained chefs may be hard to hire tonight. A longer adjustment period normally lets producers invest and train workers, raising PES.</div>'),
C('Diagrams without the slope trap','<p>Label price vertically and quantity per period horizontally. Compare responsiveness for the same percentage price change. A straight supply line through the origin has unit PES throughout; a vertical line has zero PES.</p><div class="example">Price rises 10% and output rises 5%: PES = 0.5. If output rises 20% instead, PES = 2. Comparing visually steep lines drawn with different scales is unreliable.</div>'),
C('HL: why harvests are different',H+'<p>Primary commodities often face biological growing times, weather dependence, fixed land or extraction limits. These can make short-run PES lower than for manufactured goods produced with spare factory capacity.</p><p>Storage and adjustment time matter: stored grain can respond differently from fresh fish, and a factory already at capacity may also have inelastic supply. Inelastic demand and supply together can turn modest harvest changes into large price swings.</p><div class="tip">Explain: name a concrete production constraint and link it to a limited percentage output response.</div>')],
labs:[S('How quickly can sellers respond?',['More elastic supply','Less elastic supply'],[['Empty production shifts are available',0],['Goods are easy to store',0],['Only one specialist cooker exists tonight',1],['The crop needs a full growing season',1],['Workers can transfer quickly between stalls',0],['Extra output causes sharply rising costs',1]])],
worked:W('The kitchen response','<p>Use the original values as bases.</p>'+tbl(['Measure','Before','After'],[['Meal price (DKK)','50','55'],['Bowls per hour','100','105']]),[['What is the price change?','(55 − 50) / 50 × 100 = 10%.'],['What is the quantity-supplied change?','(105 − 100) / 100 × 100 = 5%.'],['What is PES?','5 / 10 = 0.5: supply is price inelastic over this change.'],['Could that change next year?','Yes. More cookers and trained workers could remove capacity limits and make supply more responsive.']],'Elasticity is about responsiveness over a stated period, not a permanent property of the product.'),
quiz:[N('Calculate PES.',[['Price change','+10%'],['Quantity supplied change','+5%']],0.5,'5 / 10 = 0.5: inelastic.'),Q('Which makes supply more responsive tonight?',['Available stored stock','A fixed harvest next year','No spare equipment','Highly specialised immobile workers'],0,'Stocks can be released without immediately producing new units.'),T('A longer adjustment period always guarantees perfectly elastic supply.',false,'Time may remove constraints, but land, technology, inputs and costs can still limit response.'),Q('A vertical supply curve has PES…',['Zero','One','Infinity','Negative two'],0,'Quantity supplied is fixed despite price changes.'),Q(H+'Why can fresh-fruit supply be price inelastic in the short run?',['Growing time constrains new output','Fruit has unlimited storage life','All land can change instantly','Consumers set growing times'],0,'Biological production takes time even when the market price increases.'),N('Predict the percentage output response using the stated PES.',[['PES','2'],['Price change','+5%']],10,'Percentage quantity change = 2 × 5% = 10%.','%')],
explain:'Text the organiser why stored snacks can respond faster than fresh strawberries. Include the time period and one exception.'
},
{
id:'2.7a',title:'Taxes and subsidies: who pays?',emoji:'🧾',minutes:14,hl:'part',goal:'analyse indirect taxes and subsidies, stakeholder effects and HL tax-incidence calculations.',
hook:'<p>The council adds a per-cup tax on sugary drinks. The stall says customers will pay all of it. Another stall receives a subsidy for healthy meals. Does the person named on the tax or subsidy receive the whole economic burden or benefit?</p>',
cards:[C('The tax wedge','<p>An <b>indirect tax</b> is charged on spending on goods or services. A <b>specific tax</b> is a fixed amount per unit; an <b>ad valorem tax</b> is a percentage of value.</p><p>A per-unit tax shifts supply vertically upward by the tax, creating a wedge between the buyer’s price and the seller’s net receipt. Quantity traded normally falls. Tax revenue is the per-unit tax times the after-tax quantity.</p><div class="example">Buyers pay 46 and sellers retain 36: the tax wedge is DKK 10 per cup.</div>'),
C('Incidence follows responsiveness','<p><b>Tax incidence</b> is how a tax burden is divided between buyers and sellers. The relatively less elastic side bears more of the burden. The firm’s legal duty to remit the tax does not determine its economic incidence.</p><p>Without a corrective externality benefit, lost mutually beneficial trades create <b>welfare loss</b>: a reduction in total social surplus. Tax revenue is transferred to government; it is not itself the welfare-loss triangle.</p><div class="tip">Draw both buyer and seller prices and the lower traded quantity. Compare elasticities, not who writes the cheque.</div>'),
C('Subsidy support','<p>A <b>subsidy</b> is a government payment supporting production or consumption. A per-unit producer subsidy shifts supply down by the payment. Buyers generally pay less, sellers receive the buyer price plus subsidy and traded output rises.</p><p>The benefit is shared according to relative elasticities. Government spending equals subsidy per unit times subsidised quantity. Funding has an opportunity cost and, without an external benefit, extra output can create welfare loss.</p>'),
C('HL: measure the areas',H+F`\text{Tax revenue}=t\times Q_t`+F`\text{Buyer burden/unit}=P_b-P_0`+F`\text{Seller burden/unit}=P_0-P_s`+F`DWL=\frac12\times t\times(Q_0-Q_t)`+'<p>The triangle formula assumes straight curves and no offsetting externality. A health tax can also reduce external costs, so its net welfare effect needs more information. Evaluate effects on low-income consumers, jobs, substitution and enforcement.</p>')],
labs:[S('Follow the wedge',['Buyer price','Seller receipt','Government budget'],[['Price on the receipt after a tax',0],['Buyer price minus per-unit tax',1],['Tax times after-tax quantity',2],['Buyer price plus producer subsidy',1],['Subsidy times subsidised quantity is spending',2]])],
worked:W('Who bears the DKK 10 tax?','<p>Fictional straight-line market, with no externality.</p>'+tbl(['Measure','DKK or cups'],[['Original price','40'],['New buyer price','46'],['New seller receipt','36'],['Original / new quantity','100 / 80']]),[['HL: what is the buyer burden per unit?','46 − 40 = DKK 6. Buyers bear 60% of the DKK 10 wedge.'],['HL: what is the seller burden per unit?','40 − 36 = DKK 4. Sellers bear 40%.'],['HL: what is tax revenue?','(46 − 36) × 80 = DKK 800, not DKK 1,000: use the after-tax quantity.'],['HL: what is the welfare loss?','0.5 × 10 × (100 − 80) = DKK 100, under these assumptions.']],'Distinguish the transfer to government from trades that disappear.'),
quiz:[Q('A specific tax is…',['A fixed amount per unit','Always a percentage of income','A transfer to every producer','A maximum legal price'],0,'A per-unit amount differs from an ad valorem percentage tax.'),Q('Which side bears more of a tax, other things equal?',['The relatively less elastic side','The side legally remitting it always','Only sellers','Only foreign consumers'],0,'Less responsive buyers or sellers find it harder to avoid the tax burden.'),N(H+'Find government tax revenue.',[['Tax per cup (DKK)','10'],['Cups sold after tax','80']],800,'10 × 80 = DKK 800.','DKK'),N(H+'Find the buyer burden per cup.',[['Original price (DKK)','40'],['New buyer price (DKK)','46']],6,'46 − 40 = DKK 6.','DKK'),T('Government tax revenue is identical to the welfare-loss triangle.',false,'Revenue is a transfer; welfare loss measures lost net benefits from reduced trades under the model assumptions.'),Q('A producer subsidy normally…',['Lowers buyer price and raises traded quantity','Raises buyer price and lowers quantity always','Has no budget cost','Is received entirely by consumers always'],0,'Lower effective production costs increase supply; benefits are normally shared.')],
explain:'Text a stall why it cannot simply assume customers pay the whole drinks tax. Include elasticity and the difference between revenue and welfare loss.'
},
{
id:'2.7b',title:'Price controls and direct provision',emoji:'🏷️',minutes:13,hl:'part',goal:'analyse binding price ceilings and floors and evaluate regulation and public provision.',
hook:'<p>HarbourFest caps meal prices to protect teenagers’ budgets. Stalls cut output and queues grow. A farmer nearby asks for a guaranteed minimum price instead. Who benefits when a price cannot move to clear the market?</p>',
cards:[C('A maximum price','<p>A <b>price ceiling</b> is a legal maximum price. It is binding below equilibrium. Quantity demanded then exceeds quantity supplied, creating a shortage.</p><p>Low prices help those who obtain the product, but queues, rationing, lower quality and informal resale may emerge. Actual legal sales cannot exceed the amount supplied at the controlled price. A ceiling above equilibrium does not bind.</p><div class="example">At the capped meal price, buyers want 150 meals but stalls offer 90: the shortage is 60 meals.</div>'),
C('A minimum price','<p>A <b>price floor</b> is a legal minimum price. It binds above equilibrium and normally creates excess supply. A minimum wage is a labour-market price floor in the competitive model; employment effects depend on the market and model used.</p><p>Farm price support may require government purchases of unsold output. Producers who sell benefit, but consumers pay more and taxpayers fund storage or disposal. A floor below equilibrium does not bind.</p>'),
C('Other ways to intervene','<p><b>Regulation</b> uses rules and standards, such as food-safety limits. <b>Direct provision</b> means government supplies or funds a good or service rather than relying entirely on private market sales.</p><div class="example">The council can fund school meals, inspect kitchens or support supply instead of only capping prices. Provision can improve access, but requires finance, information and effective delivery.</div>'),
C('HL: count quantities, then judge',H+'<p>Shortage is quantity demanded minus quantity supplied at a binding ceiling. Surplus is quantity supplied minus quantity demanded at a binding floor. If government buys all surplus, spending equals the support price times that surplus.</p><p>Evaluate short-run access against longer-run supply incentives, quality, enforcement, fiscal costs and unintended effects. A policy can improve one group’s welfare while disadvantaging another.</p><div class="tip">Evaluate: specify who can actually buy or sell at the controlled price before claiming that everyone gains.</div>')],
labs:[S('Does the control bind?',['Binding ceiling','Binding floor','Non-binding control'],[['Maximum price below equilibrium',0],['Minimum price above equilibrium',1],['Maximum price above equilibrium',2],['Minimum price below equilibrium',2],['A legal cap that creates excess demand',0]])],
worked:W('Affordable meals, empty trays','<p>At the legal price cap the following plans apply.</p>'+tbl(['Measure','Meals per day'],[['Quantity demanded','150'],['Quantity supplied','90']]),[['HL: what is the shortage?','150 − 90 = 60 meals per day.'],['How many legal meals can be traded?','At most 90 in this simple model, because that is the available supply.'],['Who benefits and who loses?','Successful buyers pay less. Unserved buyers may queue or go without; some producers lose sales or margin.'],['What complementary policy could help?','A targeted meal subsidy or public provision may increase access, but it requires funding and monitoring.']],'A lower posted price is not the same as universal access.'),
quiz:[Q('A binding price ceiling is set…',['Below equilibrium','Above equilibrium','Exactly at every seller’s cost','Only by private buyers'],0,'A maximum price constrains the market only when it is lower than the clearing price.'),N(H+'Calculate the shortage at a price cap.',[['Quantity demanded','150'],['Quantity supplied','90']],60,'150 − 90 = 60 meals.','meals'),Q('A binding price floor normally creates…',['Excess supply','Excess demand','Zero output necessarily','No fiscal issue ever'],0,'At the higher controlled price, sellers offer more than buyers demand.'),T('A price ceiling above equilibrium necessarily creates a shortage.',false,'It is non-binding if the market-clearing price is already below the ceiling.'),N(H+'Government buys all excess farm output. Find spending.',[['Support price (DKK/unit)','20'],['Quantity supplied','150'],['Private quantity demanded','100']],1000,'Surplus = 50; spending = 20 × 50 = DKK 1,000.','DKK'),Q('Which judgement recognises a price-cap trade-off?',['Some buyers pay less, but shortages may exclude others','All consumers automatically receive more','No producer changes output','Queues remove scarcity'],0,'Distribution and actual availability matter alongside the price.')],
explain:'Text the organiser why a cheap posted meal price might mean a longer queue. Recommend one complementary action and name its cost.'
},
{
id:'2.8a',title:'Externalities: benefits and costs beyond the stall',emoji:'🌿',minutes:15,hl:'part',goal:'distinguish four externalities, draw private/social gaps and evaluate corrective policies.',
hook:'<p>The festival’s generator powers your favourite set but fills a neighbour’s bedroom with fumes. A first-aid course makes your volunteer safer and can help other visitors too. Neither effect is fully priced in the transaction. How much activity would society actually want?</p>',
cards:[C('People outside the transaction','<p>An <b>externality</b> is a cost or benefit affecting a third party that is not reflected in the market price. <b>Market failure</b> occurs when the market allocates resources inefficiently, reducing potential social surplus.</p><p><b>Marginal private cost (MPC)</b> is extra cost to the producer; <b>marginal social cost (MSC)</b> includes external costs. <b>Marginal private benefit (MPB)</b> accrues to the consumer; <b>marginal social benefit (MSB)</b> includes external benefits.</p>'+F`MSC=MPC+MEC`+F`MSB=MPB+MEB`),
C('Four gaps, two directions','<p>Negative production externality: MSC lies above MPC, such as generator pollution. Negative consumption externality: MSB lies below MPB, such as second-hand smoke. Both normally produce too much activity in the uncorrected market.</p><p>Positive production externality: MSC lies below MPC, such as knowledge spillovers from research. Positive consumption externality: MSB lies above MPB, such as protection of others through vaccination. Both normally produce too little activity.</p><p>The market chooses MPB = MPC; the social optimum is MSB = MSC. Draw price/cost/benefit vertically and quantity horizontally, label every curve, then mark Qm and Qopt. Shade lost net social benefit between them.</p>'+externalDiagram),
C('Match policy to the gap','<p>A <b>corrective tax</b> can internalise external costs; ideally it equals marginal external cost at the efficient quantity. Subsidies or public provision can support external benefits. Regulation, education and information can also change behaviour.</p><div class="example">A generator-emissions charge rewards cleaner alternatives; an equipment standard caps harm more directly. Charging per cup does not target emissions as precisely as charging the pollution itself.</div>'),
C('HL: welfare and policy evaluation',H+'<p>For straight marginal curves, welfare loss is the triangle between social benefit and social cost over the overproduced or underproduced units.</p>'+F`DWL=\frac12\times\text{quantity gap}\times\text{marginal welfare gap}`+'<p>The vertical gap used is at the market quantity for the standard linear triangle. Governments may not know the external cost, enforcement can be expensive, and demand may be unresponsive. Compare benefits, administration, stakeholder effects and the risk of incorrect tax or subsidy rates.</p><div class="tip">Explain: connect the third-party effect to a labelled private/social wedge, then show the wrong market quantity.</div>')],
labs:[S('Which externality?',['Negative production','Negative consumption','Positive production','Positive consumption'],[['Generator fumes harm neighbouring residents',0],['Second-hand smoke harms another visitor',1],['New sound-tech research helps other producers',2],['Vaccination reduces infection risks to others',3],['Factory discharge harms river users',0],['Training in emergency response helps bystanders',3]])],
worked:W('Price the generator’s damage','<p>Illustrative straight marginal curves.</p>'+tbl(['Measure','Value'],[['Unregulated output','100 units'],['Efficient output','80 units'],['Marginal welfare gap at market output','DKK 10']]),[['Which curves diverge?','For negative production externality, MSC exceeds MPC. With no consumption externality, MPB = MSB.'],['Why does the market overproduce?','Private decisions ignore the third-party damage; MPB = MPC occurs beyond MSB = MSC.'],['HL: what welfare loss is shown?','0.5 × (100 − 80) × 10 = DKK 100, for the stated straight-curve triangle.'],['What tax should be considered?','A tax equal to marginal external cost at the efficient output, not automatically the welfare gap at market output. Measure damage and check enforcement.']],'Distinguish the external-cost wedge from the net social welfare gap.'),
quiz:[Q('For a negative production externality…',['MSC exceeds MPC','MPB must equal zero','MSC is below MPC','MSB must exceed MPB'],0,'Production imposes extra third-party costs beyond private costs.'),Q('Vaccination that protects other people is usually modelled as…',['A positive consumption externality','A negative production externality','A private good with no spillover necessarily','Excess supply by definition'],0,'Other people gain from an individual’s consumption.'),Q('The social optimum is where…',['MSB equals MSC','MPB always equals zero','MPC equals average revenue regardless of spillovers','Tax revenue is greatest'],0,'The final unit’s social benefit equals its social cost.'),N(H+'Find welfare loss in the specified linear diagram.',[['Quantity gap (units)','20'],['Marginal welfare gap at market output (DKK)','10']],100,'0.5 × 20 × 10 = DKK 100.','DKK'),T('A tax equal to the external cost is always easy to set accurately.',false,'Damage varies, information is imperfect and monitoring may be costly.'),Q('A positive production externality generally causes the market to…',['Underproduce relative to the social optimum','Overproduce in every case','Produce the efficient amount automatically','Eliminate third-party benefits'],0,'Producers do not capture all spillover benefits, so private incentives are too weak.')],
explain:'Text a neighbour why a generator’s private cost differs from its social cost. Suggest a policy and explain what information the council needs.'
},
{
id:'2.8b',title:'Common resources and a sustainable festival',emoji:'🐟',minutes:12,hl:false,goal:'explain common-resource overuse and compare collective, market and regulatory responses.',
hook:'<p>The harbour looks big enough for everyone to fish. Each festival food stall buys more local catch, but fish stocks begin to fall. No stall alone wants to stop while rivals keep buying. Can the community protect a resource that many people can use?</p>',
cards:[C('Shared access, competing use','<p>A <b>common access resource</b> is rivalrous but difficult to exclude people from using. One person’s use reduces what remains for others. Fish stocks and an unmanaged grazing area can fit this model.</p><p>Open access can give users an incentive to take resources before others do, ignoring effects on future availability. This is sometimes called the tragedy of the commons; it is a risk under particular institutions, not proof that cooperation is impossible.</p>'),
C('Present benefits, future costs','<p>Overfishing reduces breeding stocks and future livelihoods. Pollution can also degrade a resource shared across borders. The market price may omit damage to other users and future generations.</p><div class="example">Cheaper fish meals today may reduce future catches. Higher current output therefore does not guarantee higher long-run economic well-being. Sustainable use must consider replenishment rates and ecological thresholds.</div>'),
C('Compare the institutions','<p><b>Tradable permits</b> create a limited number of rights to emit or extract; trading rewards lower-cost reductions. The cap and enforcement determine environmental effectiveness.</p><p>Quotas, protected zones, seasons and licensing can limit use. Local <b>collective self-governance</b> can set shared rules, monitor use and sanction breaches. Clear access rights can help, but privatisation is difficult for some resources and can exclude vulnerable users.</p>'),
C('Cooperation needs design','<p>International agreements matter when pollution or stocks cross borders. Countries may prefer others to bear the costs, disagree over fairness or lack monitoring capacity.</p><div class="example">Harbour communities could agree catch limits, use common stock surveys and provide support for affected fishing households. A paper quota without monitoring may change little.</div><div class="tip">Evaluate: compare environmental effectiveness, monitoring costs, equity and political feasibility. Explain why one arrangement fits the resource and community.</div>')],
labs:[S('Rivalry and access',['Common access resource','Private good','Policy response'],[['An open fishery where catches reduce the stock',0],['A purchased sandwich you can exclude others from eating',1],['A monitored catch quota',2],['A shared grazing area with no exclusion',0],['Tradable extraction rights under an enforced cap',2]])],
worked:W('Design a harbour fishery rule','<p>The community wants a viable breeding stock and continuing local livelihoods.</p>',[['Why does open access create a problem?','Each fisher captures their own sale revenue but shares the future stock damage with others.'],['What rule could change the incentive?','A monitored total catch cap with allocated rights, or community-agreed limits with credible sanctions.'],['What could undermine it?','Illegal fishing, poor stock estimates, cross-border catches or a cap that is politically set too high.'],['How would you judge success?','Track stock recovery, total catches, incomes, compliance costs and who receives the fishing rights.']],'A resource needs an enforceable institution, not just a slogan about individual responsibility.'),
quiz:[Q('A common access resource is…',['Rivalrous and difficult to exclude users from','Non-rivalrous and fully excludable','Always privately owned and free from scarcity','Identical to a pure public good'],0,'Use competes with others’ use, while access is hard to restrict.'),T('Shared resources can never be managed successfully by communities.',false,'Collective rules, monitoring and sanctions can support sustainable management under suitable conditions.'),Q('What determines the environmental quantity under a permit system?',['The enforced total cap','Permit price alone regardless of the cap','The name of the permit market','Every firm’s revenue'],0,'The cap limits authorised aggregate emissions or extraction.'),Q('Why can overfishing persist?',['Users ignore part of the future cost imposed on others','Fish cannot ever be scarce','Private and social costs always coincide','Every user owns the entire future stock'],0,'Individual incentives can favour current extraction over shared future benefits.'),Q('A challenge for cross-border environmental agreements is…',['Monitoring and incentives to free ride','The absence of any interdependence','That pollution always stays within borders','That enforcement has no cost'],0,'Benefits may be shared while compliance costs fall on individual countries.'),Q('Which evidence best assesses the fishing rule?',['Stock, compliance, incomes and access over time','Only the number of posters printed','Only the initial quota announcement','Only meal prices on one day'],0,'Effectiveness and distribution require outcome data over a suitable period.')],
explain:'Text the fish stalls a shared rule that protects the harbour. Explain how it would be monitored and who might need support.'
},
{
id:'2.9',title:'Public goods and the free-rider problem',emoji:'💡',minutes:10,hl:false,goal:'identify public goods and evaluate public provision and contracting out.',
hook:'<p>HarbourFest needs warning sirens for dangerous weather. Once the alarm sounds, nearby visitors hear it even if they refused to contribute. A private seller struggles to collect enough payments. Who should organise the service?</p>',
cards:[C('Two defining properties','<p>A <b>public good</b> is both non-rivalrous and non-excludable. <b>Non-rivalrous</b> means one person’s use does not reduce availability to others. <b>Non-excludable</b> means preventing non-payers from benefiting is difficult.</p><div class="example">A local warning signal can protect many people simultaneously, including non-payers. A ticketed concert is excludable and can become rivalrous when capacity is tight; government funding does not itself make something a public good.</div>'),
C('Why a seller may not supply enough','<p>The <b>free-rider problem</b> arises when people can benefit without paying, weakening voluntary payment and private provision. Even people who value the siren may wait for others to fund it.</p><p>The result can be underprovision or non-provision relative to the social optimum. This is about incentives to reveal willingness to pay, not proof that nobody values the service.</p>'),
C('Funding and production can differ','<p>Government can fund provision through taxation, reducing reliance on voluntary payments. It may produce the service directly or use <b>contracting out</b>: paying a private supplier to deliver it.</p><div class="example">The council funds weather alarms but a specialist company installs and maintains them. Private production with public finance can still deliver a public good.</div>'),
C('What should the contract require?','<p>Compare reliability, coverage, cost, accountability and access. Contracting may use expertise and competitive bids, but weak contracts or limited competition can cause poor maintenance or expensive renewals.</p><p>Tax finance has an opportunity cost. Some goods are public only over a local area or until congestion arises. State the relevant setting before classifying them.</p><div class="tip">Explain: apply both non-rivalry and non-excludability, then connect free riding to weak payment incentives.</div>')],
labs:[S('Classify the festival goods',['Public good in this setting','Private good','Common access resource'],[['A warning siren audible to the whole local area',0],['A meal that one buyer eats',1],['An open fish stock depleted by catches',2],['A ticketed seat in a full venue',1],['A local flood-warning broadcast open to all',0]])],
worked:W('Fund the alarm','<p>The alarm benefits all visitors within earshot, and non-payers cannot easily be excluded.</p>',[['Why is it non-rivalrous?','One extra person hearing the warning does not reduce anyone else’s ability to hear it.'],['Why is private charging difficult?','Non-payers still hear the warning, so some people may withhold payment and free ride.'],['What public response is possible?','Tax-funded council provision, either produced directly or delivered by a contracted specialist.'],['What should evaluation include?','Coverage, test results, maintenance incentives, the procurement process and alternative uses of the budget.']],'Separate who finances a service from who physically produces it.'),
quiz:[Q('A pure public good has which properties?',['Non-rivalrous and non-excludable','Rivalrous and excludable','Rivalrous and non-excludable','Non-rivalrous and always excludable'],0,'Both properties together define a pure public good.'),T('Every service paid for by government is a public good.',false,'Classification depends on rivalry and excludability, not the source of finance.'),Q('Free riding can cause…',['Underprovision through weak payment incentives','Unlimited private revenue','No social benefit','Perfect knowledge of willingness to pay'],0,'People may wait for others to fund benefits they can receive without paying.'),Q('Contracting out means…',['Government pays a private supplier to deliver a service','Every user pays voluntarily','Government must manufacture all equipment itself','The good becomes rivalrous automatically'],0,'Public funding and private production can be combined.'),Q('Which is a private good?',['A meal eaten by one ticket holder','A non-excludable local siren','National defence in the standard model','An open warning broadcast'],0,'A meal is rivalrous and its seller can exclude non-payers.'),Q('Which matters when assessing a siren contract?',['Reliability, coverage and maintenance incentives','Only the supplier’s logo','Whether tax money has no opportunity cost','The claim all bidding is costless'],0,'The public objective is an effective service, delivered at justified cost.')],
explain:'Tell a mate why a publicly funded meal is not automatically a public good, then explain why an emergency warning might be.'
},
{
id:'2.10',title:'HL: hidden information and hidden actions',emoji:'🔎',minutes:12,hl:true,goal:'distinguish adverse selection and moral hazard and evaluate private and government responses.',
hook:'<p>A second-hand sound desk looks perfect but its seller knows it overheats. Later, a fully insured hire company stops checking its cables as carefully. Both involve information gaps, but at different stages. How can buyers and insurers protect themselves?</p>',
cards:[C('One side knows more',H+'<p><b>Asymmetric information</b> occurs when one party in a transaction has more relevant information than the other. Trades may then be missing, wrongly priced or socially inefficient.</p><div class="example">The sound-desk seller knows its repair history; a buyer sees only the listing. Uncertainty can lower what buyers will pay even for genuinely reliable equipment.</div>'),
C('Before versus after',H+'<p><b>Adverse selection</b> concerns hidden information before contracting: higher-risk or lower-quality participants may be disproportionately selected. If buyers offer only a low average price, good-quality sellers may withdraw.</p><p><b>Moral hazard</b> concerns hidden actions or changed incentives after an agreement: protection from consequences can encourage more risk or less care. An insured firm might take less care of equipment if insurers cannot observe it.</p>'),
C('Private information tools',H+'<p><b>Signalling</b> occurs when the better-informed party credibly communicates quality, for example through a costly warranty or recognised qualification. <b>Screening</b> occurs when the less-informed party obtains information, for example through inspection or a risk questionnaire.</p><p>Deductibles, monitoring and contract conditions can reduce moral hazard by retaining incentives for care. They can also impose costs or exclude people who need protection.</p>'),
C('Public responses and limits',H+'<p>Disclosure rules, product standards, licensing, inspections and public information can reduce information gaps. Their success depends on credible data and enforcement.</p><div class="example">A mandatory safety history helps the sound-desk buyer only if reports are accurate and understandable. Certification can become a barrier to entry; a warranty can be worthless if the seller disappears.</div><div class="tip">Distinguish: specify the hidden information before contract or hidden behaviour after it. Evaluate the response against that mechanism.</div>')],
labs:[S('Find the information problem',['Adverse selection','Moral hazard','Signalling','Screening'],[['A seller hides pre-existing amplifier damage',0],['An insured firm takes less care after cover begins',1],['A seller offers a credible repair warranty',2],['A buyer orders an independent inspection',3],['An insurer asks applicants about past claims',3]])],
worked:W('Buy the sound desk safely','<p>The seller knows more about the desk’s condition than Freja does.</p>',[['What is the initial market risk?','Hidden quality before purchase creates adverse selection. Good desks may leave if buyers will pay only a low average price.'],['What could the seller do?','Offer a credible warranty or verified maintenance record: signalling by the informed party.'],['What could Freja do?','Commission an independent test: screening by the less-informed buyer.'],['What information problem might remain after insurance?','If care is hard to observe and losses are fully covered, the owner may take less care: moral hazard. Monitoring or a deductible can retain incentives.']],'Name who provides or obtains the information before labelling a response.'),
quiz:[Q('A seller knows a desk is faulty before sale. The key problem is…',['Adverse selection','Moral hazard after insurance','Public-good rivalry','A price floor'],0,'Relevant hidden quality exists before the transaction.'),Q('An insured firm becomes less careful after taking out cover. This is…',['Moral hazard','Adverse selection only','Perfect information','A demand shift caused by income'],0,'Protection changes incentives for behaviour after the agreement.'),Q('The informed seller offers a credible warranty. This is…',['Signalling','Screening by the buyer','A binding price ceiling','An external benefit by definition'],0,'The better-informed party communicates quality.'),Q('The buyer hires an independent engineer to inspect equipment. This is…',['Screening','Signalling by the seller','A tax incidence calculation','A public good by definition'],0,'The less-informed party seeks information.'),T('Full insurance always improves incentives to prevent losses.',false,'If actions are hidden, reducing the personal cost of loss can weaken incentives for care.'),Q('Why might a disclosure rule fail?',['Information may be false, complex or unenforced','Every buyer already has perfect information','Standards have no cost','Disclosure removes all risk automatically'],0,'Useful information must be accurate, understandable and enforceable.')],
explain:'Text Freja how to distinguish a hidden fault before buying from careless use after insurance. Give one response to each.'
},
{
id:'2.11a',title:'HL: costs, revenue and profit decisions',emoji:'🧮',minutes:15,hl:true,goal:'calculate cost, revenue and profit measures and apply the marginal profit rule.',
hook:'<p>The noodle stall takes lots of cash but still struggles to pay for equipment and the owner’s time. Freja thinks more sales must mean more profit. The next batch adds revenue and cost. How do you decide whether it is worth producing?</p>',
cards:[C('Count economic costs',H+'<p><b>Economic cost</b> includes explicit payments and implicit opportunity costs, such as the owner’s forgone earnings. <b>Normal profit</b> is the minimum return required to keep entrepreneurship in its current use and is included in economic cost.</p><p><b>Fixed cost</b> does not vary with output in the short run; <b>variable cost</b> does. The short run has at least one fixed input; in the long run all inputs can vary.</p>'+F`TC=FC+VC`),
C('Total, average and extra',H+F`AC=\frac{TC}{Q},\quad MC=\frac{\Delta TC}{\Delta Q}`+F`AR=\frac{TR}{Q},\quad MR=\frac{\Delta TR}{\Delta Q}`+'<p><b>Average cost (AC)</b> is cost per unit. <b>Marginal cost (MC)</b> is the extra cost per additional unit. Average revenue is revenue per unit; marginal revenue is extra revenue per additional unit. If all units sell at one price, AR equals price. A price-making firm may need to cut the price of all units to sell more, so MR lies below AR.</p>'),
C('Follow the margin',H+F`\pi=TR-TC=(AR-AC)Q`+'<p>Profit maximisation occurs where MC = MR and MC crosses MR from below, or where no feasible output change raises profit. Before that point, an extra unit with MR greater than MC adds profit; beyond it, an extra unit with MC greater than MR reduces profit.</p><p><b>Abnormal profit</b> means revenue exceeds economic cost; normal profit means they are equal. Losses mean AR is below AC at the chosen output. The profit-maximising output may still make a loss.</p>'),
C('Why scale can help',H+'<p><b>Economies of scale</b> reduce long-run average cost as scale expands, through specialisation, bulk buying or spreading large indivisible equipment costs. Diseconomies of scale raise long-run average cost through coordination problems or other disadvantages of size.</p><p>Diminishing marginal returns concerns a variable input with fixed inputs in the short run; economies of scale concern changing scale in the long run. On a cost/revenue diagram, label cost and revenue vertically, output horizontally, MC, AC, AR and MR, and find the quantity at MC = MR before reading price and AC.</p><div class="tip">Calculate: distinguish levels from changes, divide by output where required and include implicit costs in economic profit.</div>')],
labs:[S('Choose the measure',['Total measure','Per-unit average','Marginal measure'],[['All economic costs for the period',0],['Total cost divided by output',1],['Change in revenue from the next unit',2],['Total sales receipts',0],['Change in cost per extra unit',2],['Revenue per unit sold',1]])],
worked:W('Does one more batch help?','<p>Each batch has ten bowls; costs include the owner’s normal return.</p>'+tbl(['Batches','Total revenue (DKK)','Total cost (DKK)'],[['4','2,000','1,600'],['5','2,500','1,900'],['6','3,000','2,500']]),[['What is profit at five batches?','2,500 − 1,900 = DKK 600.'],['Does moving from four to five help?','Extra revenue is 500; extra cost is 300. Profit rises by DKK 200.'],['Does moving from five to six help?','Extra revenue is 500; extra cost is 600. Profit falls by DKK 100. Five is better among the listed outputs.'],['What are AR and AC at five batches?','There are 50 bowls. AR = 2,500 / 50 = DKK 50; AC = 1,900 / 50 = DKK 38. Profit = (50 − 38) × 50 = DKK 600.']],'Use the actual change in quantity when calculating a marginal value.'),
quiz:[N('Find economic profit.',[['Total revenue (DKK)','2,500'],['Total economic cost (DKK)','1,900']],600,'2,500 − 1,900 = DKK 600.','DKK'),N('Find average cost per bowl.',[['Total cost (DKK)','1,900'],['Bowls produced','50']],38,'1,900 / 50 = DKK 38 per bowl.','DKK/bowl'),N('Find MC per extra bowl.',[['Increase in total cost (DKK)','300'],['Additional bowls','10']],30,'300 / 10 = DKK 30 per extra bowl.','DKK/bowl'),Q('When MR exceeds MC, an additional unit usually…',['Raises profit','Lowers profit necessarily','Leaves profit unchanged always','Makes fixed costs variable'],0,'Extra revenue exceeds extra cost.'),T('Normal profit is excluded from economic cost.',false,'Normal profit is the opportunity cost of entrepreneurship and is part of economic cost.'),Q('Economies of scale refer to…',['Falling long-run average cost as scale expands','A guaranteed fall in every short-run marginal cost','Higher prices by definition','Only adding workers to a fixed cooker'],0,'All inputs can vary in the long-run scale comparison.')],
explain:'Text the stall owner why high sales revenue can coexist with low economic profit. Then explain the extra-unit decision rule.'
},
{
id:'2.11b',title:'HL: perfect and monopolistic competition',emoji:'🏪',minutes:14,hl:true,goal:'compare competitive structures, short/long-run profits and efficiency outcomes.',
hook:'<p>Several stalls sell identical sealed water bottles. Others sell distinctive meals with their own branding. Customers react differently to a small price increase in the two markets. What can entry and product differences tell you about profits?</p>',
cards:[C('A benchmark with no price power',H+'<p><b>Perfect competition</b> has many small firms, homogeneous products, free entry and exit and relevant information. Each firm is a <b>price taker</b>: it cannot influence the market price.</p>'+F`P=AR=MR`+'<p>The firm’s demand is horizontal at the market price, even though market demand slopes down. Choose output where rising MC meets MR. At that output, price above AC gives abnormal profit; price equal to AC gives normal profit; price below AC gives a loss.</p>'),
C('Entry changes the long run',H+'<p>Abnormal profits attract entry, increasing market supply and pushing price down. Losses encourage exit, reducing supply and pushing price up. Under the standard assumptions, long-run equilibrium has normal profit and firms produce at minimum AC.</p><p><b>Productive efficiency</b> means production at the lowest possible average cost for the relevant technology. Allocative efficiency requires price equal to marginal cost when there are no externalities. The perfect-competition benchmark can meet both in long-run equilibrium.</p>'),
C('Branding creates some power',H+'<p><b>Monopolistic competition</b> has many firms, relatively free entry and differentiated products. Each firm faces downward-sloping demand because its offering is distinctive, but many substitutes constrain price power.</p><div class="example">HarbourFest’s noodle stall can charge slightly more for its recipe and service, but cannot ignore nearby meal stalls. It chooses MC = MR and reads price from AR.</div>'),
C('Variety has a trade-off',H+'<p>In monopolistic competition, entry erodes abnormal profit until the firm’s demand is tangent to AC. The standard long-run model has normal profit, price above MC and output below minimum-AC capacity.</p><p>This creates allocative inefficiency and excess capacity relative to the benchmark, but consumers gain product variety. A comparison should weigh those benefits as well as price and cost. A normal-profit outcome does not imply perfect competition.</p><div class="tip">Draw firm and market diagrams separately. Mark MC = MR output first, then use AR for price and AC for profit.</div>')],
labs:[S('Which competitive structure?',['Perfect competition','Monopolistic competition','Both in standard long-run equilibrium'],[['Homogeneous products and price-taking firms',0],['Differentiated products and many sellers',1],['Normal economic profit after free entry adjusts',2],['Horizontal demand for each small firm',0],['A downward firm demand curve constrained by substitutes',1]])],
worked:W('A branded stall meets new rivals','<p>The stall currently charges DKK 50, has AC of DKK 40 and sells 100 bowls.</p>',[['What is current economic profit?','(50 − 40) × 100 = DKK 1,000, assuming the chosen output maximises profit.'],['What does free entry do?','New differentiated competitors reduce demand for the existing stall and make substitutes more available.'],['What is the standard long-run result?','Demand is tangent to AC at normal profit. The stall still faces downward demand and generally charges above MC.'],['Does variety have value?','Yes. Different recipes, service and locations can benefit consumers, so assess variety alongside inefficiency.']],'Long-run normal profit can arise in different structures with different efficiency properties.'),
quiz:[Q('A perfectly competitive firm faces…',['Horizontal demand at the market price','The whole downward market demand curve as a monopolist','No marginal revenue','A legal minimum price necessarily'],0,'It is too small to influence the market price.'),Q('Abnormal profit under free entry tends to…',['Attract firms and erode existing firms’ profit','Prevent any new entry automatically','Guarantee permanent monopoly','Make demand disappear'],0,'Entry expands competitive supply or alternatives.'),N('Find the branded stall’s profit.',[['Price (DKK)','50'],['AC (DKK)','40'],['Output','100']],1000,'(50 − 40) × 100 = DKK 1,000.','DKK'),T('Normal profit proves that a firm is allocatively efficient.',false,'Monopolistic competition can have normal profit with price above marginal cost.'),Q('Which is typical of monopolistic competition?',['Many differentiated suppliers and relatively free entry','One firm with no close substitutes','Identical products and horizontal firm demand','Only government-owned producers'],0,'Differentiation creates some price power despite many substitutes.'),Q('The standard long-run perfect-competition benchmark has…',['P = MC and production at minimum AC','P above MC necessarily','Permanent abnormal profit with free entry','Only one seller'],0,'Under the assumptions, it achieves allocative and productive efficiency.')],
explain:'Text a friend why both water stalls and branded meal stalls may earn normal profit but face different demand curves and efficiency outcomes.'
},
{
id:'2.11c',title:'HL: monopoly, welfare and regulation',emoji:'👑',minutes:14,hl:true,goal:'analyse monopoly profit and welfare, natural monopoly and the trade-offs of regulation.',
hook:'<p>Only one company can supply the festival’s electricity connection. It sets a high price and the organiser cannot easily switch. Yet duplicating the whole cable network could be wasteful. Should the council break it up, regulate it or run it?</p>',
cards:[C('Barriers protect market power',H+'<p><b>Market power</b> is the ability to influence price or market conditions. A <b>monopoly</b> is a single or dominant supplier in a market with high entry barriers and no close substitutes. Patents, network control, legal restrictions, scale economies or customer lock-in can protect it.</p><p>A monopolist is a price maker, but cannot choose any price and quantity independently: market demand constrains sales. MR is below downward-sloping AR when one price applies to all units.</p>'),
C('Find quantity before price',H+'<p>Choose output where rising MC crosses MR. Read price from the demand/AR curve at that output. Compare that price with AC to find abnormal profit, normal profit or loss.</p><p>Compared with the competitive P = MC outcome on the same cost and demand curves, monopoly normally restricts output and raises price. With no externalities, P above MC means some socially beneficial trades do not occur, producing welfare loss. A monopolist can still make losses if demand is weak or costs high.</p>'+firmDiagram),
C('When one network costs less',H+'<p>A <b>natural monopoly</b> occurs when economies of scale allow one firm to supply the whole relevant market at lower average cost than several smaller firms. Large fixed network costs can make average cost fall over the relevant demand range.</p><div class="example">One cable connection may be cheaper than duplicate networks. Marginal-cost pricing can improve allocative efficiency but may leave revenue below total cost. Average-cost pricing allows normal profit but usually leaves price above MC.</div>'),
C('Control power, preserve useful scale',H+'<p>Government can regulate prices or service quality, block anticompetitive practices, impose fines or use public ownership. Breaking up a natural monopoly can lose scale economies; regulation depends on cost information and can weaken incentives if poorly designed.</p><p>Large firms may finance research and innovation with profits, but profit does not guarantee investment. Evaluate prices, access, quality, innovation, production costs and accountability over time.</p><div class="tip">Analyse: show MC = MR, price on AR, the profit rectangle (P − AC) × Q and the welfare-loss region between demand and MC.</div>')],
labs:[S('Regulating the network',['Potential benefit','Potential limitation'],[['Lower regulated prices improve access',0],['Regulator cannot accurately observe costs',1],['One network avoids wasteful duplication',0],['Breaking the network removes scale economies',1],['Abnormal profits can fund research',0],['Profit does not guarantee useful innovation',1]])],
worked:W('The electricity network’s profit','<p>At its profit-maximising output:</p>'+tbl(['Measure','Value'],[['Quantity','100 connections'],['Price / AR','DKK 80'],['Average cost','DKK 50'],['Marginal cost','DKK 30']]),[['What is profit?','(80 − 50) × 100 = DKK 3,000.'],['Why is the result allocatively inefficient?','Price 80 exceeds marginal cost 30; some potential extra connections have benefits above their extra cost.'],['Why not assume a break-up helps?','If it is a natural monopoly, duplicate networks could raise average cost.'],['What regulation could be assessed?','A price and service-quality rule or public ownership. Compare access, investment, costs and the information required to enforce it.']],'An evaluation weighs lower prices against incentives, scale and regulatory information.'),
quiz:[Q('A single-price monopolist sets its output where…',['MC = MR with the appropriate crossing','Price equals MR at every output','AC is always zero','Demand is perfectly elastic'],0,'Quantity is selected at the margin; the selling price comes from demand.'),N('Calculate monopoly profit.',[['Price / AR (DKK)','80'],['AC (DKK)','50'],['Quantity','100']],3000,'(80 − 50) × 100 = DKK 3,000.','DKK'),T('A monopolist can charge any price and sell any chosen quantity independently.',false,'Market demand constrains how much buyers will purchase at each price.'),Q('A natural monopoly is defined by…',['Cost conditions favouring one supplier for the market','Any company with a popular logo','A guaranteed social benefit from high prices','Only legal ownership by government'],0,'Economies of scale make one supplier lower-cost over the relevant output range.'),Q('Why can marginal-cost pricing require a subsidy in a natural monopoly?',['Price may be below average cost','Marginal cost is always above average cost','Every monopoly has zero fixed costs','Consumers necessarily pay more than before'],0,'With falling AC, MC can be below AC, leaving total revenue insufficient to cover cost.'),Q('Which is a balanced judgement about monopoly profit?',['It may finance innovation, but investment is not guaranteed','It always creates innovation','It proves there is no welfare loss','It proves the firm cannot make future losses'],0,'Possible dynamic benefits need evidence rather than assumption.')],
explain:'Tell the organiser why breaking up a sole electricity supplier may raise costs. Compare one regulation with public ownership.'
},
{
id:'2.11d',title:'HL: oligopoly, games and concentration',emoji:'🎲',minutes:15,hl:true,goal:'analyse interdependence, collusion incentives and payoff matrices and calculate concentration ratios.',
hook:'<p>Two large ticket platforms dominate festival bookings. Each could cut its fee to steal customers, but both fear a price war. They could both earn more by keeping fees high. What prevents that cooperative outcome from lasting?</p>',
cards:[C('A few firms watch each other',H+'<p>An <b>oligopoly</b> has a few large interdependent firms and significant entry barriers. <b>Interdependence</b> here means each firm’s best decision depends on rivals’ responses.</p><p><b>Price competition</b> changes prices or fees. <b>Non-price competition</b> uses quality, service, advertising, innovation or loyalty schemes. A price cut may gain sales if rivals hold prices, but matching cuts can trigger a price war.</p>'),
C('Collude, then be tempted to cheat',H+'<p><b>Collusion</b> is cooperation to reduce competition, for example by fixing prices or limiting output. A cartel is a formal agreement; tacit coordination can occur without explicit agreement. A collusive industry can act like a monopolist, restricting output and reducing allocative efficiency.</p><p>Each member may secretly cut price or exceed a quota to gain extra sales. Different costs, new entry, monitoring problems and competition law can weaken collusion. Cooperation that raises joint profit need not improve consumer welfare.</p>'),
C('Read a payoff matrix',H+'<p>A <b>payoff matrix</b> records outcomes for combinations of players’ actions. A <b>dominant strategy</b> gives a player a better payoff regardless of the rival’s action. A <b>Nash equilibrium</b> is a combination where neither player gains by changing their own strategy alone.</p>'+tbl(['A chooses / B chooses','B holds fee','B cuts fee'],[['A holds fee','A: 8; B: 8','A: 2; B: 10'],['A cuts fee','A: 10; B: 2','A: 4; B: 4']])+'<p>For each firm, cutting wins whether the rival holds or cuts. Both cut and earn 4 each, though both would earn 8 by holding. Payoffs are fictional DKK thousands.</p>'),
C('Measure dominance carefully',H+'<p>A <b>concentration ratio</b> is the combined market share of the largest specified number of firms.</p>'+F`CR_n=\sum_{i=1}^{n}s_i`+'<p>A high ratio can indicate limited competition, but depends on how the market is defined. Contestability, import competition, substitutes, regulation and actual conduct also matter. Competition policy can challenge collusion, scrutinise mergers and penalise abuse, with possible effects on scale and investment.</p><div class="tip">Analyse: compare each player’s payoffs while holding the rival’s strategy fixed; do not simply choose the cell with the largest joint payoff.</div>')],
labs:[S('Ticket-platform behaviour',['Price competition','Non-price competition','Collusion risk','Instability of collusion'],[['Cutting the booking fee',0],['Improving refund service',1],['Agreeing a shared minimum fee',2],['Secretly offering discounts against an agreement',3],['Developing a more reliable app',1],['A new rival undermines an agreed price',3]])],
worked:W('Will the two platforms hold fees?','<p>Use the matrix in the Learn card: holding together pays 8 each; unilateral cutting pays 10 to the cutter and 2 to the rival; cutting together pays 4 each.</p>',[['What should A do if B holds?','Cut: A receives 10 rather than 8.'],['What should A do if B cuts?','Cut: A receives 4 rather than 2. Cutting is A’s dominant strategy; symmetry gives B the same incentive.'],['What is the Nash equilibrium?','Both cut, earning 4 each. Neither can gain by switching alone to hold.'],['Why might repeated interaction differ?','Future retaliation or monitoring can support coordination, while secret discounts, new entry and enforcement can undermine it. The one-shot matrix is a simplified model.']],'Individual incentives can produce a lower joint payoff without either firm making an arithmetic mistake.'),
quiz:[Q('The defining strategic feature of oligopoly is…',['Interdependence among a few large firms','An infinite number of price-taking firms','No entry barriers','No possible non-price competition'],0,'Each large firm must consider likely rival reactions.'),N('Calculate the four-firm concentration ratio.',[['Firm 1 share','30%'],['Firm 2 share','25%'],['Firm 3 share','15%'],['Firm 4 share','10%']],80,'30 + 25 + 15 + 10 = 80%.','%'),Q('A firm gains more by cutting whether the rival holds or cuts. Cutting is…',['A dominant strategy','Proof of a cartel agreement','Always socially efficient','An average-cost curve'],0,'The action is best for that firm for every rival strategy shown.'),T('The Nash equilibrium must maximise the firms’ combined profits.',false,'A Nash equilibrium is stable against unilateral deviation; it need not maximise joint payoff.'),Q('Why might a cartel member cheat?',['A secret discount may gain extra sales','All cheating automatically raises rivals’ profits','Cartels remove every incentive','Demand is always zero'],0,'Collective restraint creates an individual temptation to capture more business.'),Q('A high concentration ratio alone cannot establish…',['The exact degree of competitive pressure','The largest firms’ combined shares','The chosen market definition’s importance','That few firms hold a large measured share'],0,'Imports, substitutes, entry threats and conduct affect competition beyond the ratio.')],
explain:'Text a mate why two ticket platforms might both cut fees even though both would earn more by keeping fees high. Mention the consumer and competition-law perspective.'
},
{
id:'2.12',title:'HL: why market income need not be fair',emoji:'🤝',minutes:11,hl:true,goal:'explain how factor ownership and market processes generate unequal income and wealth.',
hook:'<p>Two friends work equally long shifts at HarbourFest. One also owns a stage and earns rental income; the other must pay travel costs from wages alone. Their families leave them very different starting points. Does an efficient market guarantee a fair outcome?</p>',
cards:[C('Flows and stocks',H+'<p><b>Income</b> is a flow received over a period, including wages, rent, interest and profit. <b>Wealth</b> is a stock of assets minus liabilities at a point in time.</p><div class="example">A weekly wage is income. Ownership of a debt-free stage is wealth; hiring it out generates rental income. High wealth can support income without the same number of working hours.</div>'),
C('Follow factor ownership',H+'<p>In the circular flow, households supply labour, land, capital and entrepreneurship to firms and receive factor incomes. Ownership of these resources is uneven. Inheritance, education, health, discrimination, bargaining power and access to finance affect earning opportunities.</p><p>Labour pay also depends on demand for skills and productivity, not just effort. Market income reflects willingness and ability to pay for resources; it is not a measure of moral deservingness.</p>'),
C('Feedback across generations',H+'<p>Higher-income households may save more, build assets and finance education or a business. Those assets can produce more income and be inherited. Low-income households may face borrowing constraints or expensive debt.</p><div class="example">Stage ownership provides rent, which can fund a second stage. A worker without collateral may be unable to finance the same investment. This is a possible reinforcing process, not a claim that every household follows one path.</div>'),
C('Equity needs a judgement',H+'<p>Inequality means differences in a measure such as income or wealth. <b>Equity</b> concerns fairness, which depends on values and criteria. Equal incomes are not the only possible conception of fairness.</p><p>Competitive efficiency can coexist with unequal outcomes. Governments may use education, transfers, taxation and public services to change opportunities or distribution; these policies have funding and incentive trade-offs. Unit 3.4 examines poverty and distribution measures in more detail.</p><div class="tip">Explain: draw households supplying differently owned factors to firms, show the unequal income flows and connect saving to later asset ownership.</div>')],
labs:[S('Income or wealth?',['Income flow','Wealth stock','Source of unequal opportunity'],[['Wages earned this week',0],['A stage’s net asset value today',1],['Interest received this year',0],['Limited access to training',2],['Inherited debt-free property',1],['Discrimination in hiring',2]])],
worked:W('Equal hours, unequal resources','<p>Two households each earn DKK 5,000 in monthly wages. Household A also owns equipment.</p>'+tbl(['Monthly flow','A (DKK)','B (DKK)'],[['Wages','5,000','5,000'],['Equipment rent','2,000','0']]),[['What are total monthly incomes?','A receives 7,000; B receives 5,000. A’s extra income comes from asset ownership, despite equal wages.'],['How can the gap affect future wealth?','If A saves some rent and invests it, assets and future income may rise. Actual results depend on spending, returns and shocks.'],['Why is efficiency not enough to establish equity?','An efficient allocation can start from very unequal factor ownership. Whether that is fair requires a value judgement.'],['What policy could change opportunities?','Accessible training or credit support may broaden earning opportunities, but needs finance and effective targeting.']],'Separate a factual explanation of inequality from a judgement about what is fair.'),
quiz:[Q('Wealth is…',['A stock of assets minus liabilities','Only this week’s wage','A flow measured per hour','Always equal to annual consumption'],0,'Wealth is measured at a point in time, unlike income over a period.'),N('Calculate monthly income.',[['Wages (DKK)','5,000'],['Rent received (DKK)','2,000']],7000,'5,000 + 2,000 = DKK 7,000.','DKK'),T('Equal working hours necessarily produce equal household income.',false,'Wage rates and asset-derived incomes can differ, as can opportunities and constraints.'),Q('Which can reinforce inequality over time?',['Asset income finances further asset accumulation','Everyone has identical initial wealth','All households face identical credit access','Inheritance is impossible'],0,'Ownership can generate income that supports additional wealth.'),Q('An allocatively efficient market outcome…',['Can still be judged inequitable','Must distribute income equally','Has no factor payments','Proves all opportunities were equal'],0,'Efficiency and fairness answer different questions.'),Q('Which statement is a value judgement?',['Inherited wealth ought to be taxed more heavily','One household receives DKK 2,000 rent','A wage is an income flow','One household owns two stages'],0,'“Ought” expresses a normative view about fairness.')],
explain:'Text a friend why equal hours need not mean equal income. Use the circular flow and distinguish an explanation from a fairness judgement.'
}
];
// Add helpers where a taught term is reused in another lesson, preserving markup and TeX.
const termPattern = new RegExp('\\b(' + Object.keys(glossary2).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|') + ')\\b','gi');
const unit2Terms = new Map(Object.entries(glossary2).map(([key,value])=>[key.toLowerCase(),value]));
const linkTerms = (html, sec) => html.split(/(<[^>]*>|\$\$[\s\S]*?\$\$)/g).map(part=>part.startsWith('<')||part.startsWith('$$')?part:part.replace(termPattern,(text)=>unit2Terms.get(text.toLowerCase())?.sec===sec?text:`[[${text.toLowerCase()}|${text}]]`)).join('');
for (const s of sections) {
  s.cards.forEach(c=>{c.html=linkTerms(c.html,s.id);});
  s.worked.steps.forEach(step=>{step.answer=linkTerms(step.answer,s.id);});
  s.quiz.forEach((q,i)=>{q.id=`${s.id}-${i+1}`;q.why=linkTerms(q.why,s.id);});
}
